mapper.select:
select j.*, a.title as actname, a.tupian as tupian, h.accountname as joinaccount, h.name as joinname, h.touxiang as photo, h.mobile from actjoin j left join activity a on a.id=j.actid left join huiyuan h on h.id=j.hyid where 1=1
and j.hyid=#{hyid}
and j.actid=#{actid}
and j.state=#{state}
and a.title like '%${actname}%'
